import java.util.*;import model.*;import service.*;import exception.*;public class MiniBank{public static void main(String[]args){Scanner sc=new Scanner(System.in);BankService bank=new BankService();System.out.println("====================================\n       MINI BANK | CHARUSAT\n====================================");boolean run=true;while(run){System.out.println("\n1.Open Savings  2.Open Current  3.Open Fixed Deposit  4.Deposit  5.Withdraw  6.Transfer  7.Statement  8.List Accounts  9.End-of-day Report  0.Exit");System.out.print("Choose: ");String choice=sc.nextLine().trim();try{switch(choice){case "1","2","3"->{System.out.print("Owner name: ");String n=sc.nextLine();System.out.print("Opening balance: ");long b=Long.parseLong(sc.nextLine());Account a=bank.openAccount(n,b,Integer.parseInt(choice));System.out.println("Created: "+a);}case "4"->{System.out.print("Account number: ");String id=sc.nextLine();System.out.print("Amount: ");bank.deposit(id,Long.parseLong(sc.nextLine()));System.out.println("Deposit successful.");}case "5"->{System.out.print("Account number: ");String id=sc.nextLine();System.out.print("Amount: ");bank.withdraw(id,Long.parseLong(sc.nextLine()));System.out.println("Withdrawal successful.");}case "6"->{System.out.print("From account: ");String f=sc.nextLine();System.out.print("To account: ");String t=sc.nextLine();System.out.print("Amount: ");bank.transfer(f,t,Long.parseLong(sc.nextLine()));System.out.println("Transfer successful.");}case "7"->{System.out.print("Account number: ");System.out.println(bank.statement(sc.nextLine()));}case "8"->bank.listAccounts().forEach(System.out::println);case "9"->System.out.println(bank.report());case "0"->{bank.save();run=false;System.out.println("Data saved. Thank you!");}default->System.out.println("Invalid choice.");}}catch(NumberFormatException e){System.out.println("Please enter a valid whole number.");}catch(BankException e){System.out.println("Operation failed: "+e.getMessage());}catch(Exception e){System.out.println("Error: "+e.getMessage());}}}}
